/* Volta Studio — Shared Styles */
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,700;0,900;1,400;1,700&family=Source+Serif+4:ital,wght@0,300;0,400;0,600;1,300;1,400&display=swap');

/* ── Tokens ── */
:root {
  --bg:       #F5F2ED;
  --ink:      #1A1A1A;
  --ink-2:    #4A4A4A;
  --ink-3:    #7A7A7A;
  --accent:   #C4622D;
  --sand:     #D4BFA0;
  --sage:     #8A9E8A;
  --terracotta: #C4622D;
  --cream:    #EDE8E0;

  --font-serif: 'Playfair Display', Georgia, serif;
  --font-body: 'Source Serif 4', Georgia, serif;

  --space-1:  0.5rem;
  --space-2:  1rem;
  --space-3:  1.5rem;
  --space-4:  2rem;
  --space-6:  3rem;
  --space-8:  4rem;
  --space-12: 6rem;
  --space-16: 8rem;
  --space-24: 12rem;

  --max-w: 1200px;
  --gutter: clamp(1.5rem, 5vw, 4rem);

  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
}

/* ── Reset ── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 1.0625rem;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

/* ── Scrollbar ── */
::-webkit-scrollbar { width: 6px; }
::-webkit-scrollbar-track { background: var(--bg); }
::-webkit-scrollbar-thumb { background: var(--sand); border-radius: 3px; }

/* ── Typography ── */
h1, h2, h3, h4 {
  font-family: var(--font-serif);
  line-height: 1.1;
  letter-spacing: -0.02em;
}

h1 { font-size: clamp(2.8rem, 7vw, 5.5rem); font-weight: 700; }
h2 { font-size: clamp(2rem, 4vw, 3.5rem); font-weight: 700; }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.75rem); font-weight: 700; }

p { max-width: 68ch; }

a { color: inherit; text-decoration: none; }

img, video { display: block; max-width: 100%; }

/* ── Utilities ── */
.container {
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 0 var(--gutter);
}

.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* ── Header / Nav ── */
.site-header {
  position: fixed;
  top: 0; left: 0; right: 0;
  z-index: 100;
  padding: var(--space-3) var(--gutter);
  display: flex;
  align-items: center;
  justify-content: space-between;
  mix-blend-mode: normal;
  pointer-events: none;
}

.site-header > * { pointer-events: auto; }

.logo {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--ink);
}

.logo:hover { opacity: 0.7; }

.nav-desktop {
  display: flex;
  gap: var(--space-4);
  align-items: center;
}

.nav-desktop a {
  font-family: var(--font-body);
  font-size: 0.875rem;
  font-weight: 400;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--ink);
  position: relative;
  padding-bottom: 2px;
}

.nav-desktop a::after {
  content: '';
  position: absolute;
  bottom: 0; left: 0;
  width: 0; height: 1px;
  background: var(--ink);
  transition: width 0.3s var(--ease-out);
}

.nav-desktop a:hover::after { width: 100%; }

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  background: none;
  border: none;
  padding: 4px;
  z-index: 200;
}

.hamburger span {
  display: block;
  width: 24px;
  height: 1.5px;
  background: var(--ink);
  transition: transform 0.3s var(--ease-out), opacity 0.3s;
  transform-origin: center;
}

.hamburger.open span:nth-child(1) { transform: translateY(6.5px) rotate(45deg); }
.hamburger.open span:nth-child(2) { opacity: 0; }
.hamburger.open span:nth-child(3) { transform: translateY(-6.5px) rotate(-45deg); }

/* Mobile overlay */
.mobile-overlay {
  position: fixed;
  inset: 0;
  background: var(--bg);
  z-index: 150;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--space-4);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s var(--ease-out);
}

.mobile-overlay.open {
  opacity: 1;
  pointer-events: auto;
}

.mobile-overlay a {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 8vw, 3.5rem);
  font-weight: 700;
  color: var(--ink);
  letter-spacing: -0.02em;
  transition: opacity 0.2s;
}

.mobile-overlay a:hover { opacity: 0.5; }

/* ── Footer ── */
.site-footer {
  padding: var(--space-8) var(--gutter);
  border-top: 1px solid var(--cream);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--space-2);
}

.site-footer p {
  font-size: 0.8125rem;
  color: var(--ink-3);
  max-width: none;
}

/* ── Section labels ── */
.label {
  font-family: var(--font-body);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--ink-3);
}

/* ── Divider ── */
.divider {
  width: 3rem;
  height: 1px;
  background: var(--ink);
  margin: var(--space-6) 0;
}

/* ── Marquee ── */
.marquee-section {
  overflow: hidden;
  padding: var(--space-3) 0;
  border-top: 1px solid var(--cream);
  border-bottom: 1px solid var(--cream);
}

.marquee-track {
  display: flex;
  gap: 0;
  white-space: nowrap;
}

.marquee-row {
  display: flex;
  align-items: center;
  gap: 0;
  will-change: transform;
}

.marquee-row span {
  font-family: var(--font-serif);
  font-size: clamp(1rem, 2vw, 1.375rem);
  font-weight: 400;
  color: var(--ink-2);
  padding: 0 var(--space-4);
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.marquee-row span::after {
  content: '◦';
  color: var(--sand);
  font-size: 0.7em;
}

.marquee-row span:last-child::after { display: none; }

/* Alternating row speeds */
.row-1 { animation: marquee-left 28s linear infinite; }
.row-2 { animation: marquee-right 22s linear infinite; }
.row-3 { animation: marquee-left 34s linear infinite; }

@keyframes marquee-left {
  from { transform: translateX(0); }
  to   { transform: translateX(-50%); }
}

@keyframes marquee-right {
  from { transform: translateX(-50%); }
  to   { transform: translateX(0); }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  .marquee-row { animation: none; }
  .marquee-row span { padding: 0 var(--space-3); }
}

/* ── Page transitions ── */
main {
  animation: page-in 0.5s var(--ease-out) both;
}

@keyframes page-in {
  from { opacity: 0; transform: translateY(12px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* ── Responsive ── */
@media (max-width: 768px) {
  .nav-desktop { display: none; }
  .hamburger { display: flex; }
}

@media (min-width: 769px) {
  .mobile-overlay { display: none !important; }
}

